<section class="card"><h2>Start with a routine</h2><p class="muted">Each starter is added once. Clicking it again enables the existing routine and keeps your edits. Nothing runs until you choose it. Weather needs a future optional provider.</p><div class="hero-actions"><?php foreach (AutomationService::templates() as $key=>$template): ?><form method="post" action="/automation/templates"><?= csrf_field() ?><input type="hidden" name="template" value="<?= e($key) ?>"><button class="secondary">Enable <?= e($template['name']) ?></button></form><?php endforeach; ?></div><p class="footnote">The desktop resident checks schedules while LifeOS is running, including when its window is hidden. Exit LifeOS to stop it. A missed day is not replayed. Monthly rules run on the 1st; weekly reports cover the previous complete Monday–Sunday week. Reminders remain in the notification panel; Windows popups follow your notification preference.</p></section>
<section class="card" id="rule-builder"><h2><?= $editing ? 'Edit routine' : 'Build a routine' ?></h2><p class="muted">Choose a trigger → set a condition → choose an action.</p><form method="post" action="/automation/rules" class="stack"><?= csrf_field() ?><?php if ($editing): ?><input type="hidden" name="id" value="<?= e($editing['id']) ?>"><?php endif; ?><label>Name<input name="name" value="<?= e($editing['name'] ?? '') ?>" maxlength="150" required placeholder="My morning plan"></label><div class="form-grid"><fieldset class="choice-fieldset"><legend>1 · Trigger</legend><label>Schedule<select name="trigger"><?php foreach (['daily'=>'Every selected day','weekly'=>'Weekly (selected weekdays)','monthly'=>'Monthly (1st of month)','deadline'=>'Deadline ladder'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($editing['trigger'] ?? 'daily')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Time · Asia/Colombo<input type="time" name="time" value="<?= e($config['time']) ?>" required></label></fieldset><fieldset class="choice-fieldset"><legend>2 · Condition</legend><div class="choice-list"><?php foreach ($days as $number=>$label): ?><label class="choice"><input type="checkbox" name="weekdays[]" value="<?= e($number) ?>" <?= in_array($number,$config['weekdays'],true) ? 'checked' : '' ?>><span><?= e($label) ?></span></label><?php endforeach; ?></div><label>Minimum open tasks (0 = always)<input type="number" name="min_open_tasks" value="<?= e($config['min_open_tasks'] ?? 0) ?>" min="0" max="10000" required></label></fieldset><fieldset class="choice-fieldset"><legend>3 · Action</legend><?php require __DIR__.'/actions.php'; ?></fieldset></div><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?= !empty($editing['enabled']) ? 'checked' : '' ?>><span>Enable this routine</span></label><div class="hero-actions"><button>Save routine</button><?php if ($editing): ?><a href="/automation" class="btn secondary">Cancel edit</a><?php endif; ?></div></form></section>
<section class="card"><h2>Your routines</h2><?php if (!$rules): ?><div class="empty"><h3>No routines yet</h3><p>Enable a starter above or build your own routine.</p></div><?php else: foreach ($rules as $rule): $conditions=json_decode($rule['conditions'],true,32,JSON_THROW_ON_ERROR); ?><article class="task-row"><div><strong><?= e($rule['name']) ?></strong><small><?= e(ucfirst($rule['trigger'])) ?> · <?= e($conditions['time']) ?> · <?= $rule['enabled'] ? 'Enabled' : 'Paused' ?></small></div><div class="hero-actions"><a href="/automation?edit=<?= e($rule['id']) ?>#rule-builder">Edit</a><form method="post" action="/automation/rules/<?= e($rule['id']) ?>/toggle"><?= csrf_field() ?><input type="hidden" name="enabled" value="<?= $rule['enabled'] ? '0' : '1' ?>"><button class="secondary"><?= $rule['enabled'] ? 'Pause' : 'Enable' ?></button></form><form method="post" action="/automation/rules/<?= e($rule['id']) ?>/delete"><?= csrf_field() ?><button class="quiet">Remove</button></form></div></article><?php endforeach; endif; ?></section>
<section class="card"><h2>Saved reports</h2><?php if (!$reports): ?><p class="muted">Reports appear after an enabled weekly or monthly routine runs. Only your saved records are included.</p><?php else: foreach ($reports as $report): ?><div class="task-row"><a href="/automation/reports/<?= e($report['id']) ?>"><?= $report['kind']==='weekly' ? 'Weekly review' : 'Monthly money summary' ?> · <?= e($report['starts_on']) ?> to <?= e((new DateTimeImmutable($report['ends_before']))->modify('-1 day')->format('Y-m-d')) ?></a></div><?php endforeach; endif; ?></section>
<section class="card"><h2>Recent runs</h2><?php if (!$runs): ?><p class="muted">Scheduled run history will appear here.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Routine</th><th>Local date</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach ($runs as $run): ?><tr><td><?= e($run['name']) ?></td><td><?= e($run['slot']) ?></td><td><?= e(ucfirst($run['status'])) ?></td><td><?= e($run['detail']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
